BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Infective Endocarditis' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Infective Endocarditis', 'Valve infection, Duke criteria, embolic signs, treatment', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Infective Endocarditis (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Infective Endocarditis - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "Definition" is most accurate?', 'According to the Infective Endocarditis note, which statement about "Definition" is most accurate?', '[{"id": "a", "text": "Janeway lesions are painful fingertip nodules."}, {"id": "b", "text": "Endocarditis is infection of the pericardium."}, {"id": "c", "text": "Vegetations are sterile in infective cases."}, {"id": "d", "text": "Endocarditis affects the inner lining and valves."}]'::jsonb, '["d"]'::jsonb, 'Correct because Infective endocarditis is infection of the endocardium, especially heart valves, with vegetations made of fibrin, platelets, and organisms. Treat suspected valve infection urgently to limit embolic and valvular destruction.', 'Infective Endocarditis - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Valve distribution" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Valve distribution" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "b", "text": "IV drug use is primarily linked to left-sided mitral lesions."}, {"id": "c", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "d", "text": "Use risk profile to anticipate likely side/valve complications."}]'::jsonb, '["d"]'::jsonb, 'Correct because Mitral valve is commonly affected on the left side, and tricuspid involvement is common in IV drug use (right-sided). Use risk profile to anticipate likely side/valve complications.', 'Infective Endocarditis - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Organisms overview" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Organisms overview" in Infective Endocarditis?', '[{"id": "a", "text": "SIE usually occurs on completely normal valves."}, {"id": "b", "text": "Prosthetic valves are linked with S. epidermidis."}, {"id": "c", "text": "Splinter hemorrhages are diffuse trunk petechiae."}, {"id": "d", "text": "Only viral organisms cause infective endocarditis."}]'::jsonb, '["b"]'::jsonb, 'Correct because Common organisms include Streptococcus viridans, Staphylococcus aureus, Enterococcus, S. epidermidis on prosthetic valves, and HACEK organisms. Start broad directed therapy and narrow with culture data.', 'Infective Endocarditis - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Non-infective forms" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "Non-infective forms" in Infective Endocarditis?', '[{"id": "a", "text": "PATHOGENS excludes invasive procedures."}, {"id": "b", "text": "Endocarditis emboli only affect skin."}, {"id": "c", "text": "All endocarditis forms are infectious."}, {"id": "d", "text": "Non-infective vegetations lack organisms."}]'::jsonb, '["d"]'::jsonb, 'Correct because Non-infective endocarditis includes marantic (cancer/wasting) and Libman-Sacks (SLE), where vegetations have no organisms. Differentiate sterile vegetations from true infection before prolonged antimicrobials.', 'Infective Endocarditis - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "AIE profile" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "AIE profile" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Osler nodes are painless palm lesions."}, {"id": "b", "text": "A new murmur argues against endocarditis."}, {"id": "c", "text": "AIE is less destructive than subacute disease."}, {"id": "d", "text": "AIE can involve previously healthy valves."}]'::jsonb, '["d"]'::jsonb, 'Correct because Acute infective endocarditis is commonly due to S. aureus, has sudden severe onset, often attacks healthy valves, and is rapidly destructive. Escalate quickly in high-fever septic presentations with new murmur.', 'Infective Endocarditis - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "SIE profile" is most accurate?', 'According to the Infective Endocarditis note, which statement about "SIE profile" is most accurate?', '[{"id": "a", "text": "Janeway lesions are painful fingertip nodules."}, {"id": "b", "text": "SIE usually occurs on completely normal valves."}, {"id": "c", "text": "Pre-existing valve disease is commonly present in SIE."}, {"id": "d", "text": "Predisposing condition is excluded from minor criteria."}]'::jsonb, '["c"]'::jsonb, 'Correct because Subacute infective endocarditis is commonly due to S. viridans, progresses gradually over weeks to months, and usually occurs on pre-existing valve disease. Investigate prolonged low-grade constitutional symptoms in at-risk valve patients.', 'Infective Endocarditis - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "PATHOGENS mnemonic" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "PATHOGENS mnemonic" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "PATHOGENS excludes invasive procedures."}, {"id": "b", "text": "Three minor criteria alone are definitive."}, {"id": "c", "text": "Prosthetic valves are included in PATHOGENS."}, {"id": "d", "text": "Osler nodes are a vascular catheter complication."}]'::jsonb, '["c"]'::jsonb, 'Correct because Risk factors are summarized by PATHOGENS: prosthetic valve, acquired valvular disease, trauma/invasive procedures, hypertrophic cardiomyopathy, other structural defects, gram-positive risk, elderly, needles, and sepsis/bacteremia. Use mnemonic risk screening to trigger earlier blood culture and echo workup.', 'Infective Endocarditis - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Classic findings" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Classic findings" in Infective Endocarditis?', '[{"id": "a", "text": "Antibiotics should start before any cultures."}, {"id": "b", "text": "A single nonspecific fever is a major criterion."}, {"id": "c", "text": "A new murmur argues against endocarditis."}, {"id": "d", "text": "Positive blood cultures support diagnosis."}]'::jsonb, '["d"]'::jsonb, 'Correct because Fever is the most common sign, with new regurgitant murmur, chills, malaise, night sweats, splenomegaly, and positive blood cultures. Treat new murmur plus fever as high-risk until proven otherwise.', 'Infective Endocarditis - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Janeway lesions" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "Janeway lesions" in Infective Endocarditis?', '[{"id": "a", "text": "Differentiate painless Janeway lesions from painful Osler nodes at bedside."}, {"id": "b", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "c", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "d", "text": "Janeway lesions are painful fingertip nodules."}]'::jsonb, '["a"]'::jsonb, 'Correct because Janeway lesions are painless flat red spots on palms and soles from embolic phenomena. Differentiate painless Janeway lesions from painful Osler nodes at bedside.', 'Infective Endocarditis - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Osler nodes" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "Osler nodes" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "b", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "c", "text": "They are categorized as immunologic phenomena in criteria."}, {"id": "d", "text": "Osler nodes are a vascular catheter complication."}]'::jsonb, '["c"]'::jsonb, 'Correct because Osler nodes are painful nodules on fingertips/toes and represent immunologic phenomena. Use painful digital lesions to strengthen diagnostic probability with other criteria.', 'Infective Endocarditis - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "Roth and splinter findings" is most accurate?', 'According to the Infective Endocarditis note, which statement about "Roth and splinter findings" is most accurate?', '[{"id": "a", "text": "Splinter hemorrhages are diffuse trunk petechiae."}, {"id": "b", "text": "Any two minor criteria are definite diagnosis."}, {"id": "c", "text": "No culture follow-up is needed after therapy starts."}, {"id": "d", "text": "Both support systemic endocarditis manifestations."}]'::jsonb, '["d"]'::jsonb, 'Correct because Roth spots are retinal hemorrhages with pale center, and splinter hemorrhages are linear nail-bed hemorrhages. Perform focused eye and nail assessment when embolic signs are suspected.', 'Infective Endocarditis - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Embolic complications" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Embolic complications" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "Right-sided disease can embolize to lungs (PE)."}, {"id": "b", "text": "Right-sided emboli primarily cause cerebral emboli."}, {"id": "c", "text": "Enterococcus is treated with no antibiotics."}, {"id": "d", "text": "MRSA is first-line treated with amoxicillin alone."}]'::jsonb, '["a"]'::jsonb, 'Correct because Vegetation embolization can cause stroke, renal infarct, and pulmonary emboli in right-sided disease. Monitor neurologic, renal, and respiratory status for embolic deterioration.', 'Infective Endocarditis - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Duke major criteria" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Duke major criteria" in Infective Endocarditis?', '[{"id": "a", "text": "Antibiotics should start before any cultures."}, {"id": "b", "text": "Negative blood cultures satisfy major criteria."}, {"id": "c", "text": "A single nonspecific fever is a major criterion."}, {"id": "d", "text": "New valve regurgitation supports major criteria."}]'::jsonb, '["d"]'::jsonb, 'Correct because Major criteria include two positive blood cultures from separate sites and evidence of endocardial involvement (echo/new regurgitation). Anchor diagnosis on objective microbiology plus valve involvement evidence.', 'Infective Endocarditis - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Duke minor criteria" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "Duke minor criteria" in Infective Endocarditis?', '[{"id": "a", "text": "Predisposing condition is excluded from minor criteria."}, {"id": "b", "text": "Immunologic findings like Osler/Roth count as minor."}, {"id": "c", "text": "Any two minor criteria are definite diagnosis."}, {"id": "d", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}]'::jsonb, '["b"]'::jsonb, 'Correct because Minor criteria include predisposition, fever >38°C, vascular phenomena, immunologic phenomena, and microbiologic evidence not meeting major. Count minor criteria carefully when major evidence is incomplete.', 'Infective Endocarditis - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Definite diagnosis combinations" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "Definite diagnosis combinations" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Dental prophylaxis is unnecessary in high-risk patients."}, {"id": "b", "text": "MRSA is first-line treated with amoxicillin alone."}, {"id": "c", "text": "One major plus three minor can establish diagnosis."}, {"id": "d", "text": "Three minor criteria alone are definitive."}]'::jsonb, '["c"]'::jsonb, 'Correct because Definite diagnosis is 2 major OR 1 major + 3 minor OR 5 minor criteria. Apply combination thresholds precisely to avoid under/over diagnosis.', 'Infective Endocarditis - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "Blood culture protocol" is most accurate?', 'According to the Infective Endocarditis note, which statement about "Blood culture protocol" is most accurate?', '[{"id": "a", "text": "Antibiotics should start before any cultures."}, {"id": "b", "text": "Preserve microbiologic yield by drawing cultures prior to first dose."}, {"id": "c", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "d", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}]'::jsonb, '["b"]'::jsonb, 'Correct because Obtain blood cultures ×3 from different sites before starting antibiotics. Preserve microbiologic yield by drawing cultures prior to first dose.', 'Infective Endocarditis - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Echo sensitivity" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Echo sensitivity" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "TTE is always more sensitive than TEE."}, {"id": "b", "text": "Murmur reassessment is unnecessary."}, {"id": "c", "text": "Echo evaluates endocardial involvement."}, {"id": "d", "text": "Vegetations are sterile in infective cases."}]'::jsonb, '["c"]'::jsonb, 'Correct because TEE is more sensitive than TTE for detecting vegetations. Escalate to TEE when suspicion remains high despite less-sensitive imaging.', 'Infective Endocarditis - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Lab trends" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Lab trends" in Infective Endocarditis?', '[{"id": "a", "text": "Valve choice is random and unrelated to risk factors."}, {"id": "b", "text": "Dental prophylaxis is unnecessary in high-risk patients."}, {"id": "c", "text": "Hematuria may suggest renal embolic involvement."}, {"id": "d", "text": "Inflammatory markers are always normal."}]'::jsonb, '["c"]'::jsonb, 'Correct because CBC can show leukocytosis, ESR/CRP can be elevated, and urinalysis can show hematuria from renal emboli. Use labs as supportive evidence while pursuing definitive criteria.', 'Infective Endocarditis - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Antibiotic duration" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "Antibiotic duration" in Infective Endocarditis?', '[{"id": "a", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "b", "text": "Ensure prolonged IV adherence and follow-up culture monitoring."}, {"id": "c", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "d", "text": "No culture follow-up is needed after therapy starts."}]'::jsonb, '["b"]'::jsonb, 'Correct because Treatment requires IV antibiotics for 4–6 weeks with organism-specific regimens and culture-confirmed clearance. Ensure prolonged IV adherence and follow-up culture monitoring.', 'Infective Endocarditis - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Organism-specific regimens" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "Organism-specific regimens" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Strep regimens include penicillin or ampicillin."}, {"id": "b", "text": "Enterococcus is treated with no antibiotics."}, {"id": "c", "text": "MRSA is first-line treated with amoxicillin alone."}, {"id": "d", "text": "Endocarditis is infection of the pericardium."}]'::jsonb, '["a"]'::jsonb, 'Correct because Examples listed: strep with penicillin/ampicillin, staph with nafcillin or vancomycin for MRSA, enterococcus with ampicillin plus gentamicin. Match regimen to probable/confirmed organism and resistance pattern.', 'Infective Endocarditis - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "Surgical indications" is most accurate?', 'According to the Infective Endocarditis note, which statement about "Surgical indications" is most accurate?', '[{"id": "a", "text": "IV drug use is primarily linked to left-sided mitral lesions."}, {"id": "b", "text": "All cases should avoid surgery regardless of deterioration."}, {"id": "c", "text": "Severe regurgitation from valve destruction is an indication."}, {"id": "d", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}]'::jsonb, '["c"]'::jsonb, 'Correct because Surgery is indicated for severe regurgitation from valve destruction, uncontrolled infection, vegetation >10 mm with embolic risk, prosthetic valve infection, or fungal endocarditis. Escalate to surgical consultation when medical therapy is insufficient or embolic risk is high.', 'Infective Endocarditis - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Nursing priorities" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Nursing priorities" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "b", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "c", "text": "Short peripheral IV rotation is preferred over stable long-term access."}, {"id": "d", "text": "Prioritize early detection of progression while maintaining reliable IV therapy."}]'::jsonb, '["d"]'::jsonb, 'Correct because Nursing priorities include cultures before antibiotics, fever monitoring, new murmur assessment, embolic surveillance, and long-term IV access care. Prioritize early detection of progression while maintaining reliable IV therapy.', 'Infective Endocarditis - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Prophylaxis" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Prophylaxis" in Infective Endocarditis?', '[{"id": "a", "text": "Prevention targets bacteremia-triggered endocarditis."}, {"id": "b", "text": "IV drug use is primarily linked to left-sided mitral lesions."}, {"id": "c", "text": "Valve choice is random and unrelated to risk factors."}, {"id": "d", "text": "Dental prophylaxis is unnecessary in high-risk patients."}]'::jsonb, '["a"]'::jsonb, 'Correct because High-risk patients should receive amoxicillin prophylaxis before dental procedures. Prevent procedure-related bacteremia in vulnerable cardiac patients.', 'Infective Endocarditis - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "NCLEX synthesis" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "NCLEX synthesis" in Infective Endocarditis?', '[{"id": "a", "text": "Fever is uncommon in endocarditis."}, {"id": "b", "text": "Culture positivity should delay treatment."}, {"id": "c", "text": "Fever plus new murmur is a key cluster."}, {"id": "d", "text": "A new murmur argues against endocarditis."}]'::jsonb, '["c"]'::jsonb, 'Correct because High-yield pattern: fever + new regurgitant murmur + positive cultures + embolic signs should trigger urgent IE workup and treatment. Treat clustered red flags as a high-acuity syndrome requiring rapid action.', 'Infective Endocarditis - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Definition" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "Definition" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "All endocarditis forms are infectious."}, {"id": "b", "text": "Valve involvement is a central feature."}, {"id": "c", "text": "Janeway lesions are retinal findings."}, {"id": "d", "text": "Vegetations are sterile in infective cases."}]'::jsonb, '["b"]'::jsonb, 'Correct because Infective endocarditis is infection of the endocardium, especially heart valves, with vegetations made of fibrin, platelets, and organisms. Treat suspected valve infection urgently to limit embolic and valvular destruction.', 'Infective Endocarditis - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "Valve distribution" is most accurate?', 'According to the Infective Endocarditis note, which statement about "Valve distribution" is most accurate?', '[{"id": "a", "text": "IV drug use is linked to right-sided (tricuspid) disease."}, {"id": "b", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "c", "text": "Valve choice is random and unrelated to risk factors."}, {"id": "d", "text": "IV drug use is primarily linked to left-sided mitral lesions."}]'::jsonb, '["a"]'::jsonb, 'Correct because Mitral valve is commonly affected on the left side, and tricuspid involvement is common in IV drug use (right-sided). Use risk profile to anticipate likely side/valve complications.', 'Infective Endocarditis - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Organisms overview" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Organisms overview" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "SIE usually occurs on completely normal valves."}, {"id": "b", "text": "Splinter hemorrhages are diffuse trunk petechiae."}, {"id": "c", "text": "Enterococcus is associated with GI/GU sources."}, {"id": "d", "text": "Only viral organisms cause infective endocarditis."}]'::jsonb, '["c"]'::jsonb, 'Correct because Common organisms include Streptococcus viridans, Staphylococcus aureus, Enterococcus, S. epidermidis on prosthetic valves, and HACEK organisms. Start broad directed therapy and narrow with culture data.', 'Infective Endocarditis - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Non-infective forms" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Non-infective forms" in Infective Endocarditis?', '[{"id": "a", "text": "Libman-Sacks is caused by S. aureus."}, {"id": "b", "text": "Endocarditis emboli only affect skin."}, {"id": "c", "text": "Libman-Sacks is associated with SLE."}, {"id": "d", "text": "Janeway lesions are retinal findings."}]'::jsonb, '["c"]'::jsonb, 'Correct because Non-infective endocarditis includes marantic (cancer/wasting) and Libman-Sacks (SLE), where vegetations have no organisms. Differentiate sterile vegetations from true infection before prolonged antimicrobials.', 'Infective Endocarditis - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "AIE profile" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "AIE profile" in Infective Endocarditis?', '[{"id": "a", "text": "AIE is less destructive than subacute disease."}, {"id": "b", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "c", "text": "Escalate quickly in high-fever septic presentations with new murmur."}, {"id": "d", "text": "Cultures should be deferred until after several antibiotic doses."}]'::jsonb, '["c"]'::jsonb, 'Correct because Acute infective endocarditis is commonly due to S. aureus, has sudden severe onset, often attacks healthy valves, and is rapidly destructive. Escalate quickly in high-fever septic presentations with new murmur.', 'Infective Endocarditis - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "SIE profile" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "SIE profile" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Investigate prolonged low-grade constitutional symptoms in at-risk valve patients."}, {"id": "b", "text": "SIE usually occurs on completely normal valves."}, {"id": "c", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "d", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}]'::jsonb, '["a"]'::jsonb, 'Correct because Subacute infective endocarditis is commonly due to S. viridans, progresses gradually over weeks to months, and usually occurs on pre-existing valve disease. Investigate prolonged low-grade constitutional symptoms in at-risk valve patients.', 'Infective Endocarditis - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "PATHOGENS mnemonic" is most accurate?', 'According to the Infective Endocarditis note, which statement about "PATHOGENS mnemonic" is most accurate?', '[{"id": "a", "text": "Osler nodes are a vascular catheter complication."}, {"id": "b", "text": "Needles/IV drug use is included in PATHOGENS."}, {"id": "c", "text": "PATHOGENS excludes invasive procedures."}, {"id": "d", "text": "Three minor criteria alone are definitive."}]'::jsonb, '["b"]'::jsonb, 'Correct because Risk factors are summarized by PATHOGENS: prosthetic valve, acquired valvular disease, trauma/invasive procedures, hypertrophic cardiomyopathy, other structural defects, gram-positive risk, elderly, needles, and sepsis/bacteremia. Use mnemonic risk screening to trigger earlier blood culture and echo workup.', 'Infective Endocarditis - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Classic findings" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Classic findings" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "A new murmur argues against endocarditis."}, {"id": "b", "text": "Fever is uncommon in endocarditis."}, {"id": "c", "text": "Roth spots are painful toe nodules."}, {"id": "d", "text": "New regurgitant murmur is a major clue."}]'::jsonb, '["d"]'::jsonb, 'Correct because Fever is the most common sign, with new regurgitant murmur, chills, malaise, night sweats, splenomegaly, and positive blood cultures. Treat new murmur plus fever as high-risk until proven otherwise.', 'Infective Endocarditis - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Janeway lesions" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Janeway lesions" in Infective Endocarditis?', '[{"id": "a", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "b", "text": "Janeway lesions are painless flat red spots on palms and soles from embolic phenomena."}, {"id": "c", "text": "Janeway lesions are painful fingertip nodules."}, {"id": "d", "text": "Cultures should be deferred until after several antibiotic doses."}]'::jsonb, '["b"]'::jsonb, 'Correct because Janeway lesions are painless flat red spots on palms and soles from embolic phenomena. Differentiate painless Janeway lesions from painful Osler nodes at bedside.', 'Infective Endocarditis - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Osler nodes" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "Osler nodes" in Infective Endocarditis?', '[{"id": "a", "text": "Use painful digital lesions to strengthen diagnostic probability with other criteria."}, {"id": "b", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "c", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "d", "text": "Osler nodes are a vascular catheter complication."}]'::jsonb, '["a"]'::jsonb, 'Correct because Osler nodes are painful nodules on fingertips/toes and represent immunologic phenomena. Use painful digital lesions to strengthen diagnostic probability with other criteria.', 'Infective Endocarditis - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Roth and splinter findings" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "Roth and splinter findings" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Splinter hemorrhages are diffuse trunk petechiae."}, {"id": "b", "text": "Predisposing condition is excluded from minor criteria."}, {"id": "c", "text": "Roth spots are retinal hemorrhages with pale centers."}, {"id": "d", "text": "No culture follow-up is needed after therapy starts."}]'::jsonb, '["c"]'::jsonb, 'Correct because Roth spots are retinal hemorrhages with pale center, and splinter hemorrhages are linear nail-bed hemorrhages. Perform focused eye and nail assessment when embolic signs are suspected.', 'Infective Endocarditis - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "Embolic complications" is most accurate?', 'According to the Infective Endocarditis note, which statement about "Embolic complications" is most accurate?', '[{"id": "a", "text": "Right-sided emboli primarily cause cerebral emboli."}, {"id": "b", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "c", "text": "Monitor neurologic, renal, and respiratory status for embolic deterioration."}, {"id": "d", "text": "Cultures should be deferred until after several antibiotic doses."}]'::jsonb, '["c"]'::jsonb, 'Correct because Vegetation embolization can cause stroke, renal infarct, and pulmonary emboli in right-sided disease. Monitor neurologic, renal, and respiratory status for embolic deterioration.', 'Infective Endocarditis - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Duke major criteria" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Duke major criteria" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "Negative blood cultures satisfy major criteria."}, {"id": "b", "text": "Echo evidence of endocardial involvement is major."}, {"id": "c", "text": "Antibiotics should start before any cultures."}, {"id": "d", "text": "A single nonspecific fever is a major criterion."}]'::jsonb, '["b"]'::jsonb, 'Correct because Major criteria include two positive blood cultures from separate sites and evidence of endocardial involvement (echo/new regurgitation). Anchor diagnosis on objective microbiology plus valve involvement evidence.', 'Infective Endocarditis - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Duke minor criteria" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Duke minor criteria" in Infective Endocarditis?', '[{"id": "a", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "b", "text": "Predisposing condition is excluded from minor criteria."}, {"id": "c", "text": "Count minor criteria carefully when major evidence is incomplete."}, {"id": "d", "text": "Cultures should be deferred until after several antibiotic doses."}]'::jsonb, '["c"]'::jsonb, 'Correct because Minor criteria include predisposition, fever >38°C, vascular phenomena, immunologic phenomena, and microbiologic evidence not meeting major. Count minor criteria carefully when major evidence is incomplete.', 'Infective Endocarditis - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Definite diagnosis combinations" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "Definite diagnosis combinations" in Infective Endocarditis?', '[{"id": "a", "text": "One major plus three minor can establish diagnosis."}, {"id": "b", "text": "Three minor criteria alone are definitive."}, {"id": "c", "text": "Enterococcus is treated with no antibiotics."}, {"id": "d", "text": "Dental prophylaxis is unnecessary in high-risk patients."}]'::jsonb, '["a"]'::jsonb, 'Correct because Definite diagnosis is 2 major OR 1 major + 3 minor OR 5 minor criteria. Apply combination thresholds precisely to avoid under/over diagnosis.', 'Infective Endocarditis - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Blood culture protocol" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "Blood culture protocol" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Fungal endocarditis is never surgical."}, {"id": "b", "text": "Culture positivity should delay treatment."}, {"id": "c", "text": "Different collection sites are required."}, {"id": "d", "text": "Antibiotics should start before any cultures."}]'::jsonb, '["c"]'::jsonb, 'Correct because Obtain blood cultures ×3 from different sites before starting antibiotics. Preserve microbiologic yield by drawing cultures prior to first dose.', 'Infective Endocarditis - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "Echo sensitivity" is most accurate?', 'According to the Infective Endocarditis note, which statement about "Echo sensitivity" is most accurate?', '[{"id": "a", "text": "Escalate to TEE when suspicion remains high despite less-sensitive imaging."}, {"id": "b", "text": "Short peripheral IV rotation is preferred over stable long-term access."}, {"id": "c", "text": "TTE is always more sensitive than TEE."}, {"id": "d", "text": "Cultures should be deferred until after several antibiotic doses."}]'::jsonb, '["a"]'::jsonb, 'Correct because TEE is more sensitive than TTE for detecting vegetations. Escalate to TEE when suspicion remains high despite less-sensitive imaging.', 'Infective Endocarditis - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Lab trends" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Lab trends" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "b", "text": "Inflammatory markers are always normal."}, {"id": "c", "text": "Use labs as supportive evidence while pursuing definitive criteria."}, {"id": "d", "text": "Cultures should be deferred until after several antibiotic doses."}]'::jsonb, '["c"]'::jsonb, 'Correct because CBC can show leukocytosis, ESR/CRP can be elevated, and urinalysis can show hematuria from renal emboli. Use labs as supportive evidence while pursuing definitive criteria.', 'Infective Endocarditis - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Antibiotic duration" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "Antibiotic duration" in Infective Endocarditis?', '[{"id": "a", "text": "A 3-day oral course is adequate."}, {"id": "b", "text": "Culture clearance monitoring is required."}, {"id": "c", "text": "Culture positivity should delay treatment."}, {"id": "d", "text": "Murmur reassessment is unnecessary."}]'::jsonb, '["b"]'::jsonb, 'Correct because Treatment requires IV antibiotics for 4–6 weeks with organism-specific regimens and culture-confirmed clearance. Ensure prolonged IV adherence and follow-up culture monitoring.', 'Infective Endocarditis - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Organism-specific regimens" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "Organism-specific regimens" in Infective Endocarditis?', '[{"id": "a", "text": "MRSA is first-line treated with amoxicillin alone."}, {"id": "b", "text": "Dental prophylaxis is unnecessary in high-risk patients."}, {"id": "c", "text": "Enterococcus regimen includes ampicillin + gentamicin."}, {"id": "d", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}]'::jsonb, '["c"]'::jsonb, 'Correct because Examples listed: strep with penicillin/ampicillin, staph with nafcillin or vancomycin for MRSA, enterococcus with ampicillin plus gentamicin. Match regimen to probable/confirmed organism and resistance pattern.', 'Infective Endocarditis - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Surgical indications" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "Surgical indications" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Severe regurgitation from valve destruction is an indication."}, {"id": "b", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "c", "text": "Cultures should be deferred until after several antibiotic doses."}, {"id": "d", "text": "All cases should avoid surgery regardless of deterioration."}]'::jsonb, '["a"]'::jsonb, 'Correct because Surgery is indicated for severe regurgitation from valve destruction, uncontrolled infection, vegetation >10 mm with embolic risk, prosthetic valve infection, or fungal endocarditis. Escalate to surgical consultation when medical therapy is insufficient or embolic risk is high.', 'Infective Endocarditis - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Infective Endocarditis note, which statement about "Nursing priorities" is most accurate?', 'According to the Infective Endocarditis note, which statement about "Nursing priorities" is most accurate?', '[{"id": "a", "text": "Nursing priorities include cultures before antibiotics, fever monitoring, new murmur assessment, embolic surveillance, and long-term IV access care."}, {"id": "b", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "c", "text": "Short peripheral IV rotation is preferred over stable long-term access."}, {"id": "d", "text": "Cultures should be deferred until after several antibiotic doses."}]'::jsonb, '["a"]'::jsonb, 'Correct because Nursing priorities include cultures before antibiotics, fever monitoring, new murmur assessment, embolic surveillance, and long-term IV access care. Prioritize early detection of progression while maintaining reliable IV therapy.', 'Infective Endocarditis - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Prophylaxis" in Infective Endocarditis. Which statement is correct?', 'The nurse is reviewing "Prophylaxis" in Infective Endocarditis. Which statement is correct?', '[{"id": "a", "text": "PATHOGENS excludes invasive procedures."}, {"id": "b", "text": "Dental prophylaxis is unnecessary in high-risk patients."}, {"id": "c", "text": "Valve choice is random and unrelated to risk factors."}, {"id": "d", "text": "Amoxicillin is the prophylactic example provided."}]'::jsonb, '["d"]'::jsonb, 'Correct because High-risk patients should receive amoxicillin prophylaxis before dental procedures. Prevent procedure-related bacteremia in vulnerable cardiac patients.', 'Infective Endocarditis - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "NCLEX synthesis" in Infective Endocarditis?', 'Which clinical judgment is most accurate regarding "NCLEX synthesis" in Infective Endocarditis?', '[{"id": "a", "text": "Fever is uncommon in endocarditis."}, {"id": "b", "text": "A new murmur argues against endocarditis."}, {"id": "c", "text": "Fever plus new murmur is a key cluster."}, {"id": "d", "text": "Culture positivity should delay treatment."}]'::jsonb, '["c"]'::jsonb, 'Correct because High-yield pattern: fever + new regurgitant murmur + positive cultures + embolic signs should trigger urgent IE workup and treatment. Treat clustered red flags as a high-acuity syndrome requiring rapid action.', 'Infective Endocarditis - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Definition" in Infective Endocarditis?', 'In rapid prioritization, which statement is most consistent with "Definition" in Infective Endocarditis?', '[{"id": "a", "text": "Endocarditis affects the inner lining and valves."}, {"id": "b", "text": "Vegetations are sterile in infective cases."}, {"id": "c", "text": "Janeway lesions are painful fingertip nodules."}, {"id": "d", "text": "Endocarditis is infection of the pericardium."}]'::jsonb, '["a"]'::jsonb, 'Correct because Infective endocarditis is infection of the endocardium, especially heart valves, with vegetations made of fibrin, platelets, and organisms. Treat suspected valve infection urgently to limit embolic and valvular destruction.', 'Infective Endocarditis - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Valve distribution" in Infective Endocarditis would the nurse recognize as correct?', 'Which conclusion about "Valve distribution" in Infective Endocarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Because embolic risk is minimal, urgent workup is unnecessary."}, {"id": "b", "text": "Use risk profile to anticipate likely side/valve complications."}, {"id": "c", "text": "IV drug use is primarily linked to left-sided mitral lesions."}, {"id": "d", "text": "Cultures should be deferred until after several antibiotic doses."}]'::jsonb, '["b"]'::jsonb, 'Correct because Mitral valve is commonly affected on the left side, and tricuspid involvement is common in IV drug use (right-sided). Use risk profile to anticipate likely side/valve complications.', 'Infective Endocarditis - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Definition" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "Definition" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Endocarditis is infection of the pericardium."}, {"id": "b", "text": "Vegetations are sterile in infective cases."}, {"id": "c", "text": "Vegetations include fibrin, platelets, and microorganisms."}, {"id": "d", "text": "Endocarditis affects the inner lining and valves."}, {"id": "e", "text": "Valve involvement is a central feature."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Infective endocarditis is infection of the endocardium, especially heart valves, with vegetations made of fibrin, platelets, and organisms.', 'Infective Endocarditis - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Valve distribution"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Valve distribution"? (Select all that apply)', '[{"id": "a", "text": "Valve choice is random and unrelated to risk factors."}, {"id": "b", "text": "IV drug use is primarily linked to left-sided mitral lesions."}, {"id": "c", "text": "Valve pattern can reflect exposure risks."}, {"id": "d", "text": "IV drug use is linked to right-sided (tricuspid) disease."}, {"id": "e", "text": "Mitral valve involvement is common."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Mitral valve is commonly affected on the left side, and tricuspid involvement is common in IV drug use (right-sided).', 'Infective Endocarditis - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Organisms overview" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Organisms overview" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Enterococcus is associated with GI/GU sources."}, {"id": "b", "text": "S. viridans and S. aureus are major pathogens listed."}, {"id": "c", "text": "HACEK organisms are excluded."}, {"id": "d", "text": "Prosthetic valves are linked with S. epidermidis."}, {"id": "e", "text": "Only viral organisms cause infective endocarditis."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Common organisms include Streptococcus viridans, Staphylococcus aureus, Enterococcus, S. epidermidis on prosthetic valves, and HACEK organisms.', 'Infective Endocarditis - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Non-infective forms" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "Non-infective forms" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Non-infective vegetations lack organisms."}, {"id": "b", "text": "Libman-Sacks is associated with SLE."}, {"id": "c", "text": "All endocarditis forms are infectious."}, {"id": "d", "text": "Libman-Sacks is caused by S. aureus."}, {"id": "e", "text": "Marantic endocarditis is a sterile form."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Non-infective endocarditis includes marantic (cancer/wasting) and Libman-Sacks (SLE), where vegetations have no organisms.', 'Infective Endocarditis - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "AIE profile" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "AIE profile" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "AIE is insidious over months."}, {"id": "b", "text": "AIE is less destructive than subacute disease."}, {"id": "c", "text": "AIE can involve previously healthy valves."}, {"id": "d", "text": "AIE onset is sudden and severe."}, {"id": "e", "text": "S. aureus is the common acute organism listed."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Acute infective endocarditis is commonly due to S. aureus, has sudden severe onset, often attacks healthy valves, and is rapidly destructive.', 'Infective Endocarditis - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "SIE profile" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "SIE profile" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Pre-existing valve disease is commonly present in SIE."}, {"id": "b", "text": "SIE typically presents as sudden sepsis."}, {"id": "c", "text": "SIE course is gradual."}, {"id": "d", "text": "SIE usually occurs on completely normal valves."}, {"id": "e", "text": "S. viridans is the common subacute organism listed."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Subacute infective endocarditis is commonly due to S. viridans, progresses gradually over weeks to months, and usually occurs on pre-existing valve disease.', 'Infective Endocarditis - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "PATHOGENS mnemonic"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "PATHOGENS mnemonic"? (Select all that apply)', '[{"id": "a", "text": "Sepsis/bacteremia source is included in PATHOGENS."}, {"id": "b", "text": "Age has no impact on risk."}, {"id": "c", "text": "Prosthetic valves are included in PATHOGENS."}, {"id": "d", "text": "PATHOGENS excludes invasive procedures."}, {"id": "e", "text": "Needles/IV drug use is included in PATHOGENS."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Risk factors are summarized by PATHOGENS: prosthetic valve, acquired valvular disease, trauma/invasive procedures, hypertrophic cardiomyopathy, other structural defects, gram-positive risk, elderly, needles, and sepsis/bacteremia.', 'Infective Endocarditis - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Classic findings" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Classic findings" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "A new murmur argues against endocarditis."}, {"id": "b", "text": "Positive blood cultures support diagnosis."}, {"id": "c", "text": "Fever is uncommon in endocarditis."}, {"id": "d", "text": "New regurgitant murmur is a major clue."}, {"id": "e", "text": "Fever is emphasized as the most common sign."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Fever is the most common sign, with new regurgitant murmur, chills, malaise, night sweats, splenomegaly, and positive blood cultures.', 'Infective Endocarditis - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Janeway lesions" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "Janeway lesions" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Janeway lesions are painful fingertip nodules."}, {"id": "b", "text": "Janeway lesions are painless."}, {"id": "c", "text": "They reflect embolic phenomena."}, {"id": "d", "text": "Janeway lesions are retinal findings."}, {"id": "e", "text": "They are found on palms/soles."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Janeway lesions are painless flat red spots on palms and soles from embolic phenomena.', 'Infective Endocarditis - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Osler nodes" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "Osler nodes" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Osler nodes are painful."}, {"id": "b", "text": "They occur on fingers or toes."}, {"id": "c", "text": "They are categorized as immunologic phenomena in criteria."}, {"id": "d", "text": "Osler nodes are painless palm lesions."}, {"id": "e", "text": "Osler nodes are a vascular catheter complication."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Osler nodes are painful nodules on fingertips/toes and represent immunologic phenomena.', 'Infective Endocarditis - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Roth and splinter findings" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "Roth and splinter findings" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Roth spots are retinal hemorrhages with pale centers."}, {"id": "b", "text": "Splinter hemorrhages appear in nail beds."}, {"id": "c", "text": "Both support systemic endocarditis manifestations."}, {"id": "d", "text": "Roth spots are painful toe nodules."}, {"id": "e", "text": "Splinter hemorrhages are diffuse trunk petechiae."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Roth spots are retinal hemorrhages with pale center, and splinter hemorrhages are linear nail-bed hemorrhages.', 'Infective Endocarditis - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Embolic complications"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Embolic complications"? (Select all that apply)', '[{"id": "a", "text": "Renal infarct is listed as an embolic complication."}, {"id": "b", "text": "Right-sided emboli primarily cause cerebral emboli."}, {"id": "c", "text": "Endocarditis emboli only affect skin."}, {"id": "d", "text": "Right-sided disease can embolize to lungs (PE)."}, {"id": "e", "text": "Stroke is an embolic complication listed."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Vegetation embolization can cause stroke, renal infarct, and pulmonary emboli in right-sided disease.', 'Infective Endocarditis - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Duke major criteria" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Duke major criteria" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Echo evidence of endocardial involvement is major."}, {"id": "b", "text": "A single nonspecific fever is a major criterion."}, {"id": "c", "text": "Two separate positive blood cultures are a major criterion."}, {"id": "d", "text": "New valve regurgitation supports major criteria."}, {"id": "e", "text": "Negative blood cultures satisfy major criteria."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Major criteria include two positive blood cultures from separate sites and evidence of endocardial involvement (echo/new regurgitation).', 'Infective Endocarditis - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Duke minor criteria" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "Duke minor criteria" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Predisposing condition is excluded from minor criteria."}, {"id": "b", "text": "Vascular phenomena count as minor criteria."}, {"id": "c", "text": "Any two minor criteria are definite diagnosis."}, {"id": "d", "text": "Fever above 38°C is a minor criterion."}, {"id": "e", "text": "Immunologic findings like Osler/Roth count as minor."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Minor criteria include predisposition, fever >38°C, vascular phenomena, immunologic phenomena, and microbiologic evidence not meeting major.', 'Infective Endocarditis - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Definite diagnosis combinations" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "Definite diagnosis combinations" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Three minor criteria alone are definitive."}, {"id": "b", "text": "Two major criteria can establish definite diagnosis."}, {"id": "c", "text": "Five minor criteria can establish diagnosis."}, {"id": "d", "text": "One major plus three minor can establish diagnosis."}, {"id": "e", "text": "One major alone is always definitive."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Definite diagnosis is 2 major OR 1 major + 3 minor OR 5 minor criteria.', 'Infective Endocarditis - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Blood culture protocol" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "Blood culture protocol" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Only one blood culture is needed."}, {"id": "b", "text": "Three culture sets are recommended."}, {"id": "c", "text": "Antibiotics should start before any cultures."}, {"id": "d", "text": "Different collection sites are required."}, {"id": "e", "text": "Cultures should be drawn before antibiotics."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Obtain blood cultures ×3 from different sites before starting antibiotics.', 'Infective Endocarditis - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Echo sensitivity"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Echo sensitivity"? (Select all that apply)', '[{"id": "a", "text": "Vegetation detection is central to diagnosis."}, {"id": "b", "text": "Echo has no role in diagnosis."}, {"id": "c", "text": "TEE is more sensitive than TTE."}, {"id": "d", "text": "Echo evaluates endocardial involvement."}, {"id": "e", "text": "TTE is always more sensitive than TEE."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: TEE is more sensitive than TTE for detecting vegetations.', 'Infective Endocarditis - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Lab trends" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Lab trends" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "ESR/CRP elevation is listed in workup."}, {"id": "b", "text": "Hematuria may suggest renal embolic involvement."}, {"id": "c", "text": "Inflammatory markers are always normal."}, {"id": "d", "text": "Leukocytosis is listed in workup."}, {"id": "e", "text": "Hematuria excludes endocarditis."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: CBC can show leukocytosis, ESR/CRP can be elevated, and urinalysis can show hematuria from renal emboli.', 'Infective Endocarditis - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Antibiotic duration" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "Antibiotic duration" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "No culture follow-up is needed after therapy starts."}, {"id": "b", "text": "A 3-day oral course is adequate."}, {"id": "c", "text": "Culture clearance monitoring is required."}, {"id": "d", "text": "IV treatment is typically 4–6 weeks."}, {"id": "e", "text": "Regimen depends on organism type."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Treatment requires IV antibiotics for 4–6 weeks with organism-specific regimens and culture-confirmed clearance.', 'Infective Endocarditis - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Organism-specific regimens" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "Organism-specific regimens" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Enterococcus is treated with no antibiotics."}, {"id": "b", "text": "MRSA is first-line treated with amoxicillin alone."}, {"id": "c", "text": "Strep regimens include penicillin or ampicillin."}, {"id": "d", "text": "Enterococcus regimen includes ampicillin + gentamicin."}, {"id": "e", "text": "MRSA coverage can require vancomycin."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Examples listed: strep with penicillin/ampicillin, staph with nafcillin or vancomycin for MRSA, enterococcus with ampicillin plus gentamicin.', 'Infective Endocarditis - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Surgical indications" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "Surgical indications" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Severe regurgitation from valve destruction is an indication."}, {"id": "b", "text": "All cases should avoid surgery regardless of deterioration."}, {"id": "c", "text": "Uncontrolled infection despite antibiotics is an indication."}, {"id": "d", "text": "Fungal endocarditis is never surgical."}, {"id": "e", "text": "Vegetation >10 mm with embolic risk is an indication."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Surgery is indicated for severe regurgitation from valve destruction, uncontrolled infection, vegetation >10 mm with embolic risk, prosthetic valve infection, or fungal endocarditis.', 'Infective Endocarditis - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Nursing priorities"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Nursing priorities"? (Select all that apply)', '[{"id": "a", "text": "Short peripheral IV rotation is preferred over stable long-term access."}, {"id": "b", "text": "Fever monitoring is emphasized."}, {"id": "c", "text": "Long-term IV access maintenance is emphasized."}, {"id": "d", "text": "Murmur reassessment is unnecessary."}, {"id": "e", "text": "New murmur assessment is emphasized."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Nursing priorities include cultures before antibiotics, fever monitoring, new murmur assessment, embolic surveillance, and long-term IV access care.', 'Infective Endocarditis - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Prophylaxis" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Prophylaxis" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Dental prophylaxis is listed for high-risk groups."}, {"id": "b", "text": "Dental prophylaxis is unnecessary in high-risk patients."}, {"id": "c", "text": "Prevention targets bacteremia-triggered endocarditis."}, {"id": "d", "text": "Prophylaxis is only after procedures."}, {"id": "e", "text": "Amoxicillin is the prophylactic example provided."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: High-risk patients should receive amoxicillin prophylaxis before dental procedures.', 'Infective Endocarditis - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "NCLEX synthesis" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "NCLEX synthesis" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Culture positivity should delay treatment."}, {"id": "b", "text": "Fever plus new murmur is a key cluster."}, {"id": "c", "text": "Embolic signs lower IE suspicion."}, {"id": "d", "text": "Embolic signs increase concern for active IE."}, {"id": "e", "text": "Positive cultures strengthen urgency."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: High-yield pattern: fever + new regurgitant murmur + positive cultures + embolic signs should trigger urgent IE workup and treatment.', 'Infective Endocarditis - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Definition" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "Definition" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Valve involvement is a central feature."}, {"id": "b", "text": "Vegetations are sterile in infective cases."}, {"id": "c", "text": "Vegetations include fibrin, platelets, and microorganisms."}, {"id": "d", "text": "Endocarditis is infection of the pericardium."}, {"id": "e", "text": "Endocarditis affects the inner lining and valves."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Infective endocarditis is infection of the endocardium, especially heart valves, with vegetations made of fibrin, platelets, and organisms.', 'Infective Endocarditis - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Valve distribution" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "Valve distribution" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Valve pattern can reflect exposure risks."}, {"id": "b", "text": "Mitral valve involvement is common."}, {"id": "c", "text": "IV drug use is primarily linked to left-sided mitral lesions."}, {"id": "d", "text": "Valve choice is random and unrelated to risk factors."}, {"id": "e", "text": "IV drug use is linked to right-sided (tricuspid) disease."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Mitral valve is commonly affected on the left side, and tricuspid involvement is common in IV drug use (right-sided).', 'Infective Endocarditis - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Organisms overview"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Organisms overview"? (Select all that apply)', '[{"id": "a", "text": "Enterococcus is associated with GI/GU sources."}, {"id": "b", "text": "S. viridans and S. aureus are major pathogens listed."}, {"id": "c", "text": "Only viral organisms cause infective endocarditis."}, {"id": "d", "text": "HACEK organisms are excluded."}, {"id": "e", "text": "Prosthetic valves are linked with S. epidermidis."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Common organisms include Streptococcus viridans, Staphylococcus aureus, Enterococcus, S. epidermidis on prosthetic valves, and HACEK organisms.', 'Infective Endocarditis - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Non-infective forms" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Non-infective forms" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Libman-Sacks is caused by S. aureus."}, {"id": "b", "text": "All endocarditis forms are infectious."}, {"id": "c", "text": "Libman-Sacks is associated with SLE."}, {"id": "d", "text": "Non-infective vegetations lack organisms."}, {"id": "e", "text": "Marantic endocarditis is a sterile form."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Non-infective endocarditis includes marantic (cancer/wasting) and Libman-Sacks (SLE), where vegetations have no organisms.', 'Infective Endocarditis - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "AIE profile" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "AIE profile" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "AIE is insidious over months."}, {"id": "b", "text": "S. aureus is the common acute organism listed."}, {"id": "c", "text": "AIE onset is sudden and severe."}, {"id": "d", "text": "AIE can involve previously healthy valves."}, {"id": "e", "text": "AIE is less destructive than subacute disease."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Acute infective endocarditis is commonly due to S. aureus, has sudden severe onset, often attacks healthy valves, and is rapidly destructive.', 'Infective Endocarditis - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "SIE profile" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "SIE profile" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "SIE typically presents as sudden sepsis."}, {"id": "b", "text": "SIE usually occurs on completely normal valves."}, {"id": "c", "text": "S. viridans is the common subacute organism listed."}, {"id": "d", "text": "SIE course is gradual."}, {"id": "e", "text": "Pre-existing valve disease is commonly present in SIE."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Subacute infective endocarditis is commonly due to S. viridans, progresses gradually over weeks to months, and usually occurs on pre-existing valve disease.', 'Infective Endocarditis - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "PATHOGENS mnemonic" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "PATHOGENS mnemonic" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Age has no impact on risk."}, {"id": "b", "text": "PATHOGENS excludes invasive procedures."}, {"id": "c", "text": "Needles/IV drug use is included in PATHOGENS."}, {"id": "d", "text": "Prosthetic valves are included in PATHOGENS."}, {"id": "e", "text": "Sepsis/bacteremia source is included in PATHOGENS."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Risk factors are summarized by PATHOGENS: prosthetic valve, acquired valvular disease, trauma/invasive procedures, hypertrophic cardiomyopathy, other structural defects, gram-positive risk, elderly, needles, and sepsis/bacteremia.', 'Infective Endocarditis - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Classic findings"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Classic findings"? (Select all that apply)', '[{"id": "a", "text": "New regurgitant murmur is a major clue."}, {"id": "b", "text": "Fever is emphasized as the most common sign."}, {"id": "c", "text": "Fever is uncommon in endocarditis."}, {"id": "d", "text": "A new murmur argues against endocarditis."}, {"id": "e", "text": "Positive blood cultures support diagnosis."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Fever is the most common sign, with new regurgitant murmur, chills, malaise, night sweats, splenomegaly, and positive blood cultures.', 'Infective Endocarditis - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Janeway lesions" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Janeway lesions" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Janeway lesions are painful fingertip nodules."}, {"id": "b", "text": "Janeway lesions are painless."}, {"id": "c", "text": "They are found on palms/soles."}, {"id": "d", "text": "They reflect embolic phenomena."}, {"id": "e", "text": "Janeway lesions are retinal findings."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Janeway lesions are painless flat red spots on palms and soles from embolic phenomena.', 'Infective Endocarditis - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Osler nodes" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "Osler nodes" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Osler nodes are painful."}, {"id": "b", "text": "They occur on fingers or toes."}, {"id": "c", "text": "Osler nodes are painless palm lesions."}, {"id": "d", "text": "They are categorized as immunologic phenomena in criteria."}, {"id": "e", "text": "Osler nodes are a vascular catheter complication."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Osler nodes are painful nodules on fingertips/toes and represent immunologic phenomena.', 'Infective Endocarditis - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Roth and splinter findings" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "Roth and splinter findings" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Roth spots are retinal hemorrhages with pale centers."}, {"id": "b", "text": "Splinter hemorrhages are diffuse trunk petechiae."}, {"id": "c", "text": "Both support systemic endocarditis manifestations."}, {"id": "d", "text": "Roth spots are painful toe nodules."}, {"id": "e", "text": "Splinter hemorrhages appear in nail beds."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Roth spots are retinal hemorrhages with pale center, and splinter hemorrhages are linear nail-bed hemorrhages.', 'Infective Endocarditis - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Embolic complications" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "Embolic complications" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Right-sided emboli primarily cause cerebral emboli."}, {"id": "b", "text": "Stroke is an embolic complication listed."}, {"id": "c", "text": "Endocarditis emboli only affect skin."}, {"id": "d", "text": "Right-sided disease can embolize to lungs (PE)."}, {"id": "e", "text": "Renal infarct is listed as an embolic complication."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Vegetation embolization can cause stroke, renal infarct, and pulmonary emboli in right-sided disease.', 'Infective Endocarditis - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Duke major criteria"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Duke major criteria"? (Select all that apply)', '[{"id": "a", "text": "A single nonspecific fever is a major criterion."}, {"id": "b", "text": "Negative blood cultures satisfy major criteria."}, {"id": "c", "text": "Echo evidence of endocardial involvement is major."}, {"id": "d", "text": "New valve regurgitation supports major criteria."}, {"id": "e", "text": "Two separate positive blood cultures are a major criterion."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Major criteria include two positive blood cultures from separate sites and evidence of endocardial involvement (echo/new regurgitation).', 'Infective Endocarditis - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Duke minor criteria" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Duke minor criteria" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Any two minor criteria are definite diagnosis."}, {"id": "b", "text": "Immunologic findings like Osler/Roth count as minor."}, {"id": "c", "text": "Predisposing condition is excluded from minor criteria."}, {"id": "d", "text": "Vascular phenomena count as minor criteria."}, {"id": "e", "text": "Fever above 38°C is a minor criterion."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Minor criteria include predisposition, fever >38°C, vascular phenomena, immunologic phenomena, and microbiologic evidence not meeting major.', 'Infective Endocarditis - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Definite diagnosis combinations" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "Definite diagnosis combinations" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Five minor criteria can establish diagnosis."}, {"id": "b", "text": "One major alone is always definitive."}, {"id": "c", "text": "Two major criteria can establish definite diagnosis."}, {"id": "d", "text": "One major plus three minor can establish diagnosis."}, {"id": "e", "text": "Three minor criteria alone are definitive."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Definite diagnosis is 2 major OR 1 major + 3 minor OR 5 minor criteria.', 'Infective Endocarditis - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Blood culture protocol" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "Blood culture protocol" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Only one blood culture is needed."}, {"id": "b", "text": "Different collection sites are required."}, {"id": "c", "text": "Three culture sets are recommended."}, {"id": "d", "text": "Cultures should be drawn before antibiotics."}, {"id": "e", "text": "Antibiotics should start before any cultures."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Obtain blood cultures ×3 from different sites before starting antibiotics.', 'Infective Endocarditis - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Echo sensitivity" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "Echo sensitivity" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "TTE is always more sensitive than TEE."}, {"id": "b", "text": "Echo has no role in diagnosis."}, {"id": "c", "text": "Echo evaluates endocardial involvement."}, {"id": "d", "text": "Vegetation detection is central to diagnosis."}, {"id": "e", "text": "TEE is more sensitive than TTE."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: TEE is more sensitive than TTE for detecting vegetations.', 'Infective Endocarditis - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Lab trends"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Lab trends"? (Select all that apply)', '[{"id": "a", "text": "Leukocytosis is listed in workup."}, {"id": "b", "text": "Hematuria may suggest renal embolic involvement."}, {"id": "c", "text": "Inflammatory markers are always normal."}, {"id": "d", "text": "Hematuria excludes endocarditis."}, {"id": "e", "text": "ESR/CRP elevation is listed in workup."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: CBC can show leukocytosis, ESR/CRP can be elevated, and urinalysis can show hematuria from renal emboli.', 'Infective Endocarditis - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Antibiotic duration" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Antibiotic duration" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Regimen depends on organism type."}, {"id": "b", "text": "IV treatment is typically 4–6 weeks."}, {"id": "c", "text": "No culture follow-up is needed after therapy starts."}, {"id": "d", "text": "A 3-day oral course is adequate."}, {"id": "e", "text": "Culture clearance monitoring is required."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Treatment requires IV antibiotics for 4–6 weeks with organism-specific regimens and culture-confirmed clearance.', 'Infective Endocarditis - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Organism-specific regimens" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "Organism-specific regimens" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "MRSA is first-line treated with amoxicillin alone."}, {"id": "b", "text": "Strep regimens include penicillin or ampicillin."}, {"id": "c", "text": "MRSA coverage can require vancomycin."}, {"id": "d", "text": "Enterococcus is treated with no antibiotics."}, {"id": "e", "text": "Enterococcus regimen includes ampicillin + gentamicin."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Examples listed: strep with penicillin/ampicillin, staph with nafcillin or vancomycin for MRSA, enterococcus with ampicillin plus gentamicin.', 'Infective Endocarditis - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Surgical indications" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "Surgical indications" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Fungal endocarditis is never surgical."}, {"id": "b", "text": "All cases should avoid surgery regardless of deterioration."}, {"id": "c", "text": "Uncontrolled infection despite antibiotics is an indication."}, {"id": "d", "text": "Vegetation >10 mm with embolic risk is an indication."}, {"id": "e", "text": "Severe regurgitation from valve destruction is an indication."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Surgery is indicated for severe regurgitation from valve destruction, uncontrolled infection, vegetation >10 mm with embolic risk, prosthetic valve infection, or fungal endocarditis.', 'Infective Endocarditis - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Nursing priorities" in Infective Endocarditis are correct? (Select all that apply)', 'Which statements about "Nursing priorities" in Infective Endocarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Fever monitoring is emphasized."}, {"id": "b", "text": "Short peripheral IV rotation is preferred over stable long-term access."}, {"id": "c", "text": "Murmur reassessment is unnecessary."}, {"id": "d", "text": "New murmur assessment is emphasized."}, {"id": "e", "text": "Long-term IV access maintenance is emphasized."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Nursing priorities include cultures before antibiotics, fever monitoring, new murmur assessment, embolic surveillance, and long-term IV access care.', 'Infective Endocarditis - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Infective Endocarditis, which findings or actions relate to "Prophylaxis"? (Select all that apply)', 'For Infective Endocarditis, which findings or actions relate to "Prophylaxis"? (Select all that apply)', '[{"id": "a", "text": "Prophylaxis is only after procedures."}, {"id": "b", "text": "Dental prophylaxis is listed for high-risk groups."}, {"id": "c", "text": "Prevention targets bacteremia-triggered endocarditis."}, {"id": "d", "text": "Dental prophylaxis is unnecessary in high-risk patients."}, {"id": "e", "text": "Amoxicillin is the prophylactic example provided."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: High-risk patients should receive amoxicillin prophylaxis before dental procedures.', 'Infective Endocarditis - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "NCLEX synthesis" in Infective Endocarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "NCLEX synthesis" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Positive cultures strengthen urgency."}, {"id": "b", "text": "Fever plus new murmur is a key cluster."}, {"id": "c", "text": "Embolic signs increase concern for active IE."}, {"id": "d", "text": "Embolic signs lower IE suspicion."}, {"id": "e", "text": "Culture positivity should delay treatment."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: High-yield pattern: fever + new regurgitant murmur + positive cultures + embolic signs should trigger urgent IE workup and treatment.', 'Infective Endocarditis - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Definition" in Infective Endocarditis? (Select all that apply)', 'Which of the following are consistent with "Definition" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Vegetations are sterile in infective cases."}, {"id": "b", "text": "Vegetations include fibrin, platelets, and microorganisms."}, {"id": "c", "text": "Valve involvement is a central feature."}, {"id": "d", "text": "Endocarditis is infection of the pericardium."}, {"id": "e", "text": "Endocarditis affects the inner lining and valves."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Infective endocarditis is infection of the endocardium, especially heart valves, with vegetations made of fibrin, platelets, and organisms.', 'Infective Endocarditis - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Valve distribution" in Infective Endocarditis? (Select all that apply)', 'During reassessment, which observations align with "Valve distribution" in Infective Endocarditis? (Select all that apply)', '[{"id": "a", "text": "Mitral valve involvement is common."}, {"id": "b", "text": "Valve choice is random and unrelated to risk factors."}, {"id": "c", "text": "IV drug use is linked to right-sided (tricuspid) disease."}, {"id": "d", "text": "Valve pattern can reflect exposure risks."}, {"id": "e", "text": "IV drug use is primarily linked to left-sided mitral lesions."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Mitral valve is commonly affected on the left side, and tricuspid involvement is common in IV drug use (right-sided).', 'Infective Endocarditis - NCLEX', true, 100, 1, true);
END $$;
